import{_ as t,o,c as i,a2 as r}from"./chunks/framework.BXzK3EA4.js";const n="/assets/image%20(144).CsnlHkCd.png",p=JSON.parse('{"title":"Playground","description":"","frontmatter":{},"headers":[],"relativePath":"playground.md","filePath":"playground.md"}'),a={name:"playground.md"};function s(l,e,d,u,c,h){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="playground" tabindex="-1">Playground <a class="header-anchor" href="#playground" aria-label="Permalink to &quot;Playground&quot;">​</a></h1><h2 id="api-playground-documentation" tabindex="-1">API Playground Documentation <a class="header-anchor" href="#api-playground-documentation" aria-label="Permalink to &quot;API Playground Documentation&quot;">​</a></h2><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>The API Playground is a web-based interface for testing Tradeboard REST API endpoints. It provides an intuitive UI to explore, test, and debug all available API endpoints without needing external tools like Postman.</p><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><h3 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><strong>Three-Panel Layout</strong>: Sidebar, request editor, and response viewer side-by-side</li><li><strong>Comprehensive Endpoint Library</strong>: Pre-configured with all Tradeboard API endpoints loaded from Bruno collection</li><li><strong>Organized Categories</strong>: Endpoints grouped by functionality (Account, Orders, Data, Utilities)</li><li><strong>Live Testing</strong>: Send requests and view responses in real-time</li><li><strong>Auto-Populated API Key</strong>: Your API key is automatically injected into request bodies</li><li><strong>Line Numbers</strong>: Both request body and response display line numbers for easy reference</li><li><strong>Prettify JSON</strong>: Format and beautify JSON request bodies with one click</li><li><strong>Response Metrics</strong>: View status code, response time, and response size</li><li><strong>Copy Options</strong>: Copy response or generate cURL command</li><li><strong>Search Functionality</strong>: Quickly find endpoints by name</li></ul><h3 id="access" tabindex="-1">Access <a class="header-anchor" href="#access" aria-label="Permalink to &quot;Access&quot;">​</a></h3><p>Navigate to: <code>http://your-host:port/playground</code></p><p><strong>Note</strong>: You must be logged in to access the Playground.</p><h3 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h3><h4 id="_1-api-key-automatic" tabindex="-1">1. API Key (Automatic) <a class="header-anchor" href="#_1-api-key-automatic" aria-label="Permalink to &quot;1. API Key (Automatic)&quot;">​</a></h4><p>Your API key is automatically managed:</p><ul><li>The API key is fetched when you open the Playground</li><li>It&#39;s automatically injected into all request bodies containing an <code>apikey</code> field</li><li>No manual copy/paste required</li></ul><h4 id="_2-select-an-endpoint" tabindex="-1">2. Select an Endpoint <a class="header-anchor" href="#_2-select-an-endpoint" aria-label="Permalink to &quot;2. Select an Endpoint&quot;">​</a></h4><p>Browse the left sidebar to find the endpoint you want to test:</p><ul><li><strong>Account</strong>: Funds, orderbook, tradebook, positionbook, holdings</li><li><strong>Orders</strong>: Place, modify, cancel orders, basket orders, split orders</li><li><strong>Data</strong>: Quotes, depth, history, search, symbols, expiry dates</li><li><strong>Utilities</strong>: Ping, instruments, margin calculator</li></ul><p>Click on any endpoint to load its configuration in the request panel.</p><h4 id="_3-customize-the-request" tabindex="-1">3. Customize the Request <a class="header-anchor" href="#_3-customize-the-request" aria-label="Permalink to &quot;3. Customize the Request&quot;">​</a></h4><p>The middle panel contains two tabs:</p><p><strong>Body Tab</strong></p><ul><li>Edit the JSON request body with line numbers</li><li>API key is automatically populated</li><li>Click <strong>Prettify</strong> to format JSON</li><li>Modify parameters as needed</li></ul><p><strong>Headers Tab</strong></p><ul><li>Shows request headers</li><li>Content-Type: application/json (default)</li></ul><h4 id="_4-send-the-request" tabindex="-1">4. Send the Request <a class="header-anchor" href="#_4-send-the-request" aria-label="Permalink to &quot;4. Send the Request&quot;">​</a></h4><ol><li>Review the URL and method in the URL bar</li><li>Click the <strong>Send</strong> button (or use the arrow icon)</li><li>View the response in the right panel</li></ol><h4 id="_5-analyze-the-response" tabindex="-1">5. Analyze the Response <a class="header-anchor" href="#_5-analyze-the-response" aria-label="Permalink to &quot;5. Analyze the Response&quot;">​</a></h4><p>The right panel shows:</p><ul><li><strong>Status Code</strong>: Color-coded (green for 2xx, red for errors)</li><li><strong>Response Time</strong>: Request duration in milliseconds</li><li><strong>Response Size</strong>: Size of the response in bytes/KB</li><li><strong>Response Body</strong>: Formatted JSON with line numbers</li><li><strong>Copy Response</strong>: Copy the JSON response</li><li><strong>Copy cURL</strong>: Generate and copy cURL command</li></ul><h3 id="endpoint-categories" tabindex="-1">Endpoint Categories <a class="header-anchor" href="#endpoint-categories" aria-label="Permalink to &quot;Endpoint Categories&quot;">​</a></h3><h4 id="account-endpoints" tabindex="-1">Account Endpoints <a class="header-anchor" href="#account-endpoints" aria-label="Permalink to &quot;Account Endpoints&quot;">​</a></h4><ul><li><strong>Analyzer Status</strong>: Check if analyzer mode is enabled</li><li><strong>Analyzer Toggle</strong>: Enable/disable analyzer mode</li><li><strong>Funds</strong>: Get account balance and margin details</li><li><strong>Orderbook</strong>: View all orders</li><li><strong>Tradebook</strong>: View executed trades</li><li><strong>Positionbook</strong>: View open positions</li><li><strong>Holdings</strong>: View long-term holdings</li></ul><h4 id="order-endpoints" tabindex="-1">Order Endpoints <a class="header-anchor" href="#order-endpoints" aria-label="Permalink to &quot;Order Endpoints&quot;">​</a></h4><ul><li><strong>Place Order</strong>: Place a single order</li><li><strong>Place Smart Order</strong>: Place order with position sizing</li><li><strong>Basket Order</strong>: Place multiple orders at once</li><li><strong>Split Order</strong>: Split large orders into smaller chunks</li><li><strong>Modify Order</strong>: Modify existing order parameters</li><li><strong>Cancel Order</strong>: Cancel a specific order</li><li><strong>Cancel All Orders</strong>: Cancel all pending orders</li><li><strong>Close Position</strong>: Close all positions for a strategy</li><li><strong>Order Status</strong>: Get status of a specific order</li><li><strong>Open Position</strong>: Check open position for a symbol</li></ul><h4 id="data-endpoints" tabindex="-1">Data Endpoints <a class="header-anchor" href="#data-endpoints" aria-label="Permalink to &quot;Data Endpoints&quot;">​</a></h4><ul><li><strong>Quotes</strong>: Get real-time quotes for a symbol</li><li><strong>Depth</strong>: Get market depth (order book)</li><li><strong>History</strong>: Get historical OHLCV data</li><li><strong>Intervals</strong>: Get supported time intervals</li><li><strong>Symbol</strong>: Get symbol details</li><li><strong>Search</strong>: Search for symbols</li><li><strong>Expiry</strong>: Get expiry dates for derivatives</li><li><strong>Option Symbol</strong>: Get option chain symbols</li><li><strong>Option Greeks</strong>: Calculate option Greeks</li><li><strong>Ticker</strong>: Get ticker data (GET request)</li></ul><h4 id="utility-endpoints" tabindex="-1">Utility Endpoints <a class="header-anchor" href="#utility-endpoints" aria-label="Permalink to &quot;Utility Endpoints&quot;">​</a></h4><ul><li><strong>Ping</strong>: Test API connectivity</li><li><strong>Instruments</strong>: Download instrument master files</li><li><strong>Margin Calculator</strong>: Calculate margin requirements</li></ul><h3 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h3><ol><li><strong>Automatic API Key</strong>: Your API key is automatically injected into requests - no manual entry needed</li><li><strong>Search Feature</strong>: Use the search box to quickly find endpoints by name</li><li><strong>Prettify JSON</strong>: Click the Prettify button to format messy JSON in the request body</li><li><strong>Line Numbers</strong>: Use line numbers to reference specific parts of requests/responses</li><li><strong>Copy cURL</strong>: Generate cURL commands to replicate requests in terminal</li><li><strong>Status Codes</strong>: <ul><li>200-299: Success (green)</li><li>400-499: Client errors (red)</li><li>500-599: Server errors (red)</li></ul></li></ol><h3 id="integration-with-collections" tabindex="-1">Integration with Collections <a class="header-anchor" href="#integration-with-collections" aria-label="Permalink to &quot;Integration with Collections&quot;">​</a></h3><p>The API Playground is built using the same endpoint definitions as:</p><ul><li>Postman Collection (<code>collections/postman/tradeboard.postman_collection.json</code>)</li><li>Bruno Collection (<code>collections/tradeboard/*.bru</code>)</li></ul><p>This ensures consistency across all testing tools.</p><h3 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><h4 id="authentication-required-error" tabindex="-1">&quot;Authentication required&quot; error <a class="header-anchor" href="#authentication-required-error" aria-label="Permalink to &quot;&quot;Authentication required&quot; error&quot;">​</a></h4><ul><li>Make sure you&#39;re logged into Tradeboard</li><li>Navigate to <code>/playground</code> while logged in</li></ul><h4 id="api-key-not-being-injected" tabindex="-1">API key not being injected <a class="header-anchor" href="#api-key-not-being-injected" aria-label="Permalink to &quot;API key not being injected&quot;">​</a></h4><ul><li>Navigate to <code>/apikey</code> to generate your API key</li><li>Refresh the Playground page after generating a key</li><li>Ensure the request body contains an <code>apikey</code> field</li></ul><h4 id="invalid-api-key-errors" tabindex="-1">Invalid API key errors <a class="header-anchor" href="#invalid-api-key-errors" aria-label="Permalink to &quot;Invalid API key errors&quot;">​</a></h4><ul><li>Navigate to <code>/apikey</code> to verify or regenerate your API key</li><li>Ensure your API key is active and not expired</li></ul><h4 id="network-errors" tabindex="-1">Network errors <a class="header-anchor" href="#network-errors" aria-label="Permalink to &quot;Network errors&quot;">​</a></h4><ul><li>Check if the Tradeboard server is running</li><li>Verify the URL in the request field is correct</li><li>Check browser console for detailed error messages</li></ul><h3 id="security-notes" tabindex="-1">Security Notes <a class="header-anchor" href="#security-notes" aria-label="Permalink to &quot;Security Notes&quot;">​</a></h3><ul><li>API keys are automatically fetched from your secure session</li><li>API keys are stored encrypted in the database</li><li>Never share your API key with others</li><li>The API Playground requires authentication (login) to access</li><li>API keys are displayed in read-only mode for security</li></ul><h3 id="future-enhancements" tabindex="-1">Future Enhancements <a class="header-anchor" href="#future-enhancements" aria-label="Permalink to &quot;Future Enhancements&quot;">​</a></h3><p>Planned features:</p><ul><li>Request history and saved responses</li><li>Favorite/starred endpoints</li><li>Environment variables support</li><li>WebSocket endpoint testing</li><li>Response diff comparison</li></ul>',58)])])}const y=t(a,[["render",s]]);export{p as __pageData,y as default};
